def _looks_like_question(text):
    if not text:
        return False
    t = text.strip()
    return t.startswith("اذكر") or "عدد ممكن" in t

def get_answers_for_question(question):
    if not question:
        return None
    q_lower = question.strip().lower()
    for keyword, answers in KEYWORD_ANSWERS.items():
        if keyword.lower() in q_lower:
            return answers
    for keyword, answers in KEYWORD_ANSWERS.items():
        if q_lower in keyword.lower():
            return answers
    return None

ANSWERS_BANK = {}

def _build_bank():
    try:
        from questions import QUESTIONS_BY_CATEGORY
    except Exception:
        return
    for category, questions in QUESTIONS_BY_CATEGORY.items():
        for q in questions:
            answers = get_answers_for_question(q)
            if answers:
                ANSWERS_BANK[q] = answers

_build_bank()

__all__ = ["ANSWERS_BANK", "KEYWORD_ANSWERS", "get_answers_for_question"]
